head.b:skin:
:root {
  --lkk-bg: #f3f5f7;
  --lkk-line: #e5e9ef;
  --lkk-text: #1f2328;
  --lkk-text-soft: #586171;
  --lkk-primary: #103a7a;
  --lkk-primary-deep: #0b2d5e;
  --lkk-accent: #d22232;
  --lkk-shadow: 0 10px 24px rgba(12, 20, 37, .05);
  --lkk-container: 1180px;
}
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body {
  margin: 0;
  min-width: 320px;
  overflow-x: hidden;
  background: var(--lkk-bg);
  color: var(--lkk-text);
  font-family: Arial, Helvetica, sans-serif;
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; overflow-wrap: anywhere; }
img { display: block; max-width: 100%; height: auto; }
.lkk-header-search { min-width: 188px; }
.lkk-container {
  width: calc(100% - 32px);
  max-width: var(--lkk-container);
  margin: 0 auto;
}
.lkk-topbar {
  background: #1e2d1d;
  color: #fff;
  font-size: 12px;
}
.lkk-topbar-inner {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;
  min-height: 38px;
}
.lkk-topbar-links {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}
.lkk-topbar a {
  color: rgba(255,255,255,.92);
  font-weight: 700;
}
.lkk-site-header {
  background: #f1f1f1;
  border-bottom: 1px solid #dfe3e7;
}
.lkk-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 92px;
  padding: 10px 0 8px;
  flex-wrap: nowrap;
}
.lkk-brand { display: flex; align-items: center; gap: 13px; min-width: 0; }
.lkk-brand-logo {
  display: block;
  width: clamp(170px, 20vw, 220px);
  height: auto;
  max-height: 56px;
  object-fit: contain;
}
.lkk-header-search {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  padding: 4px 4px 4px 12px;
  background: rgba(255,255,255,.6);
  border: 1px solid #d8dee5;
  border-radius: 2px;
}
.lkk-search-input {
  width: 145px;
  min-width: 0;
  padding: 9px 10px;
  border: 0;
  background: transparent;
  font: inherit;
  color: #1f2328;
}
.lkk-search-input:focus {
  outline: none;
}
.lkk-search-form button {
  padding: 9px 16px;
  border: 0;
  border-radius: 2px;
  background: var(--lkk-accent);
  color: #fff;
  font-weight: 700;
  cursor: pointer;
}
.lkk-nav-bar {
  background: #0f4f8d;
  border-top: 1px solid rgba(255,255,255,.12);
}
.lkk-main-nav {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0;
  width: 100%;
  min-width: 0;
  min-height: 42px;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
}
.lkk-main-nav a {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  min-height: 42px;
  padding: 8px 12px;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}
.lkk-main-nav a + a { border-left: 1px solid rgba(255,255,255,.2); }
.lkk-page { padding: 24px 0 48px; }
.lkk-breaking {
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 44px;
  margin-bottom: 16px;
  padding: 8px 12px;
  border: 1px solid #e5e9ed;
  background: #fff;
}
.lkk-breaking-label {
  flex: 0 0 auto;
  padding: 5px 9px;
  background: var(--lkk-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}
.lkk-breaking a {
  overflow: hidden;
  color: #273846;
  font-size: 13px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.lkk-news-body p {
  margin: 0;
  color: var(--lkk-text-soft);
  font-size: 12px;
  line-height: 1.55;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2; line-clamp: 2;
  line-clamp: 2;
}
.lkk-home-top {
  display: grid;
  grid-template-columns: minmax(0, 1.8fr) minmax(270px, .9fr);
  gap: 20px;
  align-items: stretch;
}
.lkk-home-feature {
  position: relative;
  min-height: 400px;
  overflow: hidden;
  background: #172a3a;
  box-shadow: var(--lkk-shadow);
}
.lkk-home-feature .lkk-home-lead-media {
  position: absolute;
  inset: 0;
  display: block;
  min-height: 0;
  background: #172a3a;
}
.lkk-home-feature .lkk-home-lead-media::after {
  position: absolute;
  inset: 35% 0 0;
  background: linear-gradient(180deg, transparent, rgba(7,18,29,.9));
  content: '';
}
.lkk-home-feature .lkk-home-lead-image {
  width: 100%;
  height: 100%;
  min-height: 0;
  object-fit: cover;
}
.lkk-home-feature .lkk-home-lead-copy {
  position: absolute;
  z-index: 1;
  right: 0;
  bottom: 0;
  left: 0;
  padding: clamp(18px, 3vw, 30px);
  color: #fff;
}
.lkk-home-feature .lkk-home-lead-kicker { color: #fff; }
.lkk-home-feature .lkk-home-lead-title {
  max-width: 760px;
  margin: 0;
  font-size: clamp(1.7rem, 3vw, 2.5rem);
  line-height: 1.12;
}
.lkk-home-feature .lkk-home-lead-title a { color: #fff; }
.lkk-home-feature .lkk-home-lead-summary { display: none; }
.lkk-home-latest {
  min-width: 0;
  padding: 16px;
  border: 1px solid #e5e9ed;
  background: #fff;
}
.lkk-home-latest .lkk-section-head {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 18px;
  margin: 0 0 6px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--lkk-accent);
}
.lkk-home-latest .lkk-section-head h2 {
  margin: 0;
  font-size: 19px;
}
.lkk-home-latest-list { display: grid; }
.lkk-mini-card {
  display: grid;
  grid-template-columns: 90px minmax(0, 1fr);
  gap: 11px;
  padding: 12px 0;
  border-bottom: 1px solid #e8ebee;
}
.lkk-mini-card-copy { min-width: 0; }
.lkk-mini-card .lkk-news-label {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  line-height: 1;
}
.lkk-mini-card-copy h3 {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  font-size: 13px;
  line-height: 1.3;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2; line-clamp: 2;
}
.lkk-archive-head { margin: 0 0 24px; padding: 8px 0 16px; border-bottom: 2px solid var(--lkk-accent); }
.lkk-archive-head h1 {
  margin: 0;
  color: #172a3a;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.08;
}
.lkk-article-shell {
  max-width: 900px;
  padding: clamp(20px, 5vw, 58px);
  border: 1px solid #e8eaed;
  background: #fff;
  box-shadow: var(--lkk-shadow);
}
.lkk-article-title {
  color: #182b3b;
  font-size: clamp(2rem, 5vw, 3.35rem);
  line-height: 1.1;
}
.lkk-post-page .lkk-page {
  width: min(1120px, calc(100% - 32px));
  max-width: 1120px;
  padding-top: 16px;
  padding-bottom: 28px;
}
@media (max-width: 980px) {
  .lkk-home-top { grid-template-columns: minmax(0, 1.45fr) minmax(250px, 1fr); }
  .lkk-home-feature { min-height: 360px; }
}
@media (max-width: 680px) {
  .lkk-header-inner { min-height: 68px; }
  .lkk-brand-logo { width: min(54vw, 190px); max-height: 48px; }
  .lkk-main-nav { width: calc(100% - 22px); min-height: 42px; }
  .lkk-main-nav a { min-height: 42px; padding: 7px 10px; }
  .lkk-home-top { grid-template-columns: 1fr; gap: 14px; }
  .lkk-home-feature { min-height: clamp(260px, 65vw, 390px); }
  .lkk-home-latest { padding: 13px; }
  .lkk-home-latest-list { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 14px; }
  .lkk-mini-card { grid-template-columns: 78px minmax(0, 1fr); }
  .lkk-container { width: calc(100% - 28px); }
}
@media (max-width: 420px) {
  .lkk-header-inner { gap: 8px; }
  .lkk-search-input { width: 78px; }
  .lkk-breaking { gap: 8px; margin-bottom: 12px; padding: 6px; }
  .lkk-breaking-label { padding: 5px 6px; font-size: 9px; }
  .lkk-breaking a { font-size: 11px; }
  .lkk-home-latest-list { grid-template-columns: 1fr; }
}

body.script:
//
(function () {
  var stylesheet = document.getElementById('lkk-theme-css');
  var stylesheetSource = 'https://cdn.jsdelivr.net/gh/liputankabarkota/lkk@refs/heads/main/head.min.css';

  function scheduleScript(fn) {
    if (window.requestIdleCallback) {
      requestIdleCallback(function () {
        fn();
      }, { timeout: 1500 });
    } else {
      setTimeout(fn, 250);
    }
  }

  function loadScripts() {
    var source = 'https://cdn.jsdelivr.net/gh/liputankabarkota/lkk@refs/heads/main/footer.js';
    var existing = document.querySelector('script[data-lkk-footer-script]');
    if (existing) return;

    var script = document.createElement('script');
    script.src = source;
    script.async = true;
    script.setAttribute('data-lkk-footer-script', 'true');
    script.onerror = function () {
      console.error('Gagal memuat skrip LKK: ' + source);
    };
    document.body.appendChild(script);
  }

  function handleStylesheetError() {
    console.error('Gagal memuat stylesheet LKK: ' + stylesheetSource);
    scheduleScript(loadScripts);
  }

  function loadScriptsAfterStylesheet() {
    scheduleScript(loadScripts);
  }

  var stylesheetState = stylesheet && stylesheet.getAttribute('data-lkk-state');
  if (stylesheetState === 'loaded') {
    loadScriptsAfterStylesheet();
  } else if (stylesheetState === 'error') {
    handleStylesheetError();
  } else {
    if (stylesheet) {
      stylesheet.addEventListener('load', loadScriptsAfterStylesheet, { once: true });
      stylesheet.addEventListener('error', handleStylesheetError, { once: true });
    } else {
      scheduleScript(loadScripts);
    }
  }
}());
//
